function hub(query) {
  const rows = `${demoRow('Примерна обява за услуга','Кратко описание на услугата, район и основна информация.','Услуга')}${demoRow('Примерен предмет за продажба','Заглавие, състояние и цена се виждат още в списъка.','Купува и продава')}${demoRow('Примерна позиция за работа','Тип работа и най-важните условия са видими без излишни стъпки.','Работа')}`;
  return `<div class="page">${pageHead('Обяви и услуги','Намери обява, услуга, работа, имот, автомобил или друго на едно място.')}<div class="shell"><div class="grid cols-3">${marketplace.map(card).join('')}</div><div class="section-head compact-head"><div><h2>Още местни раздели</h2><p>Магазини, заведения и здравни услуги са на един клик разстояние.</p></div></div><div class="special-grid">${specialist.map(x=>`<a class="special-card" href="#${x.id}"><span>${x.icon}</span>${x.title}</a>`).join('')}</div><div class="section-head compact-head"><div><h2>Последни</h2><p>Примерни карти за визуална проверка — не са реални обяви.</p></div></div>${stateContent(query,`<div class="result-list">${rows}</div>`)}</div></div>`;
}

function familyPage(title, desc, groups, opts={}) {
  const context = opts.context || title;
  const defaultResultHref = (name) => `#results?context=${encodeURIComponent(context)}&group=${encodeURIComponent(name)}&detail=${encodeURIComponent(opts.resultDetail||'listing')}&owner=${encodeURIComponent(opts.owner||'Listings')}`;
  const resultHref = (name) => opts.hrefBuilder?opts.hrefBuilder(name,defaultResultHref):defaultResultHref(name);
  const quick = (opts.quick||groups.slice(0,6)).map(item=>{
    const label=typeof item==='string'?item:item.label;
    const href=typeof item==='string'?resultHref(item):item.href;
    return `<a class="chip" href="${href}">${esc(label)}</a>`;
  }).join('');
  const cards = groups.map((g,i)=>{
    const name = Array.isArray(g)?g[0]:g;
    const subs = Array.isArray(g)?g.slice(1):[];
    return `<a class="family-card" href="${resultHref(name)}"><div class="icon">${opts.icons?.[i]||icons[i%icons.length]}</div><h3>${esc(name)}</h3>${subs.length?`<div class="sublist">${subs.slice(0,4).map(s=>`<span>${esc(s)}</span>`).join('')}</div><small>Всички ${subs.length} →</small>`:`<p>Разгледай релевантните резултати.</p><small>Отвори →</small>`}</a>`;
  }).join('');
  return `<div class="page">${pageHead(title,desc,'Обяви и услуги')}<div class="shell">${opts.notice||''}<form class="search-box" data-page-search style="max-width:760px"><input name="q" aria-label="Търсене" placeholder="${esc(opts.placeholder||'Какво търсиш?')}"><button>Търси</button></form><div class="chips">${quick}</div><div class="grid cols-3">${cards}</div><div class="page-tools"><a class="btn primary" href="${opts.add||'#add/listing'}">＋ ${esc(opts.addLabel||'Публикувай')}</a><a class="btn" href="#add/question">Не намираш? Задай въпрос</a></div></div></div>`;
}

function services(){
  const quick=['ВиК','Електро','Цялостни ремонти','Почистване на дом','Автосервиз','Транспорт, преместване и доставки'];
  const cards=serviceFamilies.map((family,i)=>`<a class="family-card" href="#service-group?group=${encodeURIComponent(family[0])}"><div class="icon">${icons[i%icons.length]}</div><h3>${esc(family[0])}</h3><div class="sublist">${family.slice(1,5).map(s=>`<span>${esc(s)}</span>`).join('')}</div><small>Всички ${family.length-1} →</small></a>`).join('');
  return `<div class="page">${pageHead('Услуги','Търси по конкретна задача. Подробните услуги се показват след избора на група.','Обяви и услуги')}<div class="shell"><form class="search-box" data-page-search style="max-width:760px"><input name="q" aria-label="Търсене" placeholder="Напр. ВиК, почистване, автосервиз, хамали…"><button>Търси</button></form><div class="chips">${quick.map(x=>`<a class="chip" href="${serviceResultsHref(x)}">${esc(x)}</a>`).join('')}</div><div class="grid cols-3">${cards}</div><div class="page-tools"><a class="btn primary" href="#add/listing?category=Услуги">＋ Предложи или потърси услуга</a><a class="btn" href="#add/question">Не намираш? Задай въпрос</a></div></div></div>`;
}
function serviceGroup(query){
  const name=query.get('group')||'';
  const family=serviceFamilies.find(f=>f[0]===name);
  if(!family) return staticPage('Услугата не е намерена','Избери друга група услуги.');
  const items=family.slice(1).map((item,i)=>`<a class="family-card" href="${serviceResultsHref(item)}"><div class="icon">${icons[i%icons.length]}</div><h3>${esc(item)}</h3><p>Разгледай подходящите обяви и предложения.</p><small>Виж резултатите →</small></a>`).join('');
  return `<div class="page">${pageHead(name,'Избери конкретната услуга, която търсиш.','Услуги')}<div class="shell"><div class="grid cols-3">${items}</div><div class="page-tools"><a class="btn primary" href="#add/listing?category=Услуги">＋ Публикувай услуга</a><a class="btn" href="#uslugi">← Всички услуги</a></div></div></div>`;
}
